{
  "title": "祠堂之谜",
  "scene": "夜幕下的老宅显得格外寂静，偶尔几声猫头鹰的叫声穿透了这沉静。你站在祠堂门口，门半开着，里面透出微弱的烛光。根据村中老人的描述，祠堂中供奉着家族先祖的牌位，但最近却常有奇怪的声音传出。门缝中，一张泛黄的纸片似乎被风吹落。是调查的时刻了。",
  "goal": "揭开怪声的来源",
  "clue": "门缝中的泛黄纸片",
  "choices": [
    {
      "id": "A",
      "text": "直接推门进入",
      "outcome": "你推开门，烛光忽明忽暗。祠堂内并没有人，只有风穿过破旧的窗棂发出怪声。你松了一口气，但忽然一阵冷风吹过，你感到背后一阵寒意。原来，纸片上写着警告：‘夜入祠堂，自求多福。’你略感不安，但毕竟找到了声音的来源。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "捡起门缝的纸片",
      "outcome": "你小心翼翼地捡起纸片，上面用毛笔字写着：‘先祖不喜喧闹，以诚相待，方可解谜。’你按照纸片上的提示，轻轻敲了敲门，然后推门而入。祠堂内，一张牌位缓缓从暗处显露，原来是一只老猫在上面玩耍，发出怪声。纸片上的提示帮助你顺利找到了真相。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "大声呼唤，问是谁在祠堂",
      "outcome": "你大声呼唤，但祠堂内没有回应，只有风声似乎变得更加刺耳。你推开门进去，发现祠堂内一片寂静。你感到一阵不安，原来，纸片上的警告是关键。你浪费了一些时间，但最终还是找到了怪声的来源。",
      "result": "fail",
      "next": "retry"
    }
  ]
}
